const overlay = document.getElementById("ai4a11y-reader-mode");
if (!overlay) return true;

const closeBtn = overlay.querySelector(".ai4a11y-reader-close");
if (!closeBtn) return false;

const rect = closeBtn.getBoundingClientRect();
if (rect.width < 24 || rect.height < 24) return false;
if (rect.right > 320) return false;

const title = overlay.querySelector(".ai4a11y-reader-title");
if (!title) return false;
const titleRect = title.getBoundingClientRect();
if (titleRect.right > 320) return false;

return true;
